package com.watchreader.fanqie;

import android.app.*;
import android.os.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import android.graphics.Bitmap;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static com.watchreader.fanqie.ReaderPlugin.*;

/** Installed only as a separate emulator test APK. Never posts to real servers. */
public final class PluginInstrumentation extends Instrumentation {
    private final JSONArray checks=new JSONArray();private final JSONArray failures=new JSONArray();
    private FanqieActivity activity;
    private volatile String stage="starting";
    interface Test {void run()throws Exception;}
    private void check(String name,boolean ok)throws Exception {if(!ok)throw new Exception(name);checks.put(name);}
    private void checkpoint(){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"test-progress.json"))){out.write(new JSONObject().put("stage",stage).put("checks",checks).put("failures",failures).toString().getBytes(StandardCharsets.UTF_8));}catch(Exception ignored){}}
    private void test(String name,Test task){stage=name;checkpoint();Bundle progress=new Bundle();progress.putString("stage",name);sendStatus(1,progress);try{task.run();}catch(Throwable e){failures.put(name+": "+e.getClass().getSimpleName()+" "+(e.getMessage()==null?"":e.getMessage().substring(0,Math.min(120,e.getMessage().length()))));}checkpoint();Bundle completed=new Bundle();completed.putString("completed",name+" checks="+checks.length()+" failures="+failures.length());sendStatus(1,completed);}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}
    private void shot(String name)throws Exception {waitForIdleSync();Bitmap image=getUiAutomation().takeScreenshot();if(image!=null)try(FileOutputStream f=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,f);}}
    private <T extends View> T find(View root,Class<T> type,String label){if(type.isInstance(root)&&(label==null||(root instanceof TextView&&((TextView)root).getText().toString().equals(label))))return type.cast(root);if(root instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)root;for(int i=0;i<g.getChildCount();i++){T v=find(g.getChildAt(i),type,label);if(v!=null)return v;}}return null;}
    private View decor(){return activity.getWindow().getDecorView();}
    private void click(String label)throws Exception {final boolean[] ok={false};main(()->{Button b=find(decor(),Button.class,label);if(b!=null){b.performClick();ok[0]=true;}});check("button:"+label,ok[0]);}
    private void awaitButton(String label)throws Exception {long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){final boolean[] found={false};main(()->found[0]=find(decor(),Button.class,label)!=null);if(found[0])return;Thread.sleep(300);}throw new Exception("UI wait timed out: "+label);}
    private void awaitText(String text)throws Exception {long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){final boolean[] found={false};main(()->found[0]=find(decor(),TextView.class,text)!=null);if(found[0])return;Thread.sleep(300);}throw new Exception("UI content wait timed out");}
    private void crownChecks()throws Exception {
        com.watchreader.ReaderView view=find(decor(),com.watchreader.ReaderView.class,null);int[] pos=new int[2];main(()->view.getLocationOnScreen(pos));check("reader-original-full-viewport",pos[0]==0&&pos[1]==0&&view.getWidth()==466&&view.getHeight()==466);check("reader-has-crown-focus",view.hasFocus());int before=view.getCharOffset();final boolean[] routed={false};
        main(()->{for(int i=0;i<3;i++){long now=SystemClock.uptimeMillis();MotionEvent.PointerProperties properties=new MotionEvent.PointerProperties();properties.id=0;MotionEvent.PointerCoords coords=new MotionEvent.PointerCoords();coords.setAxisValue(MotionEvent.AXIS_SCROLL,-.15f);MotionEvent event=MotionEvent.obtain(now,now,MotionEvent.ACTION_SCROLL,1,new MotionEvent.PointerProperties[]{properties},new MotionEvent.PointerCoords[]{coords},0,0,1,1,0,0,InputDevice.SOURCE_ROTARY_ENCODER,0);routed[0]|=activity.dispatchGenericMotionEvent(event);event.recycle();}});
        check("crown-event-routed-through-activity",routed[0]);check("crown-event-advances-page",view.getCharOffset()>before);
    }
    @Override public void onStart(){Bundle done=new Bundle();JSONObject report=new JSONObject();
        java.util.concurrent.ScheduledExecutorService watchdog=java.util.concurrent.Executors.newSingleThreadScheduledExecutor();watchdog.schedule(()->{checkpoint();Bundle timeout=new Bundle();timeout.putString("timeout_stage",stage);finish(Activity.RESULT_CANCELED,timeout);},240,java.util.concurrent.TimeUnit.SECONDS);
        try{
            Context ctx=getTargetContext();CredentialStore vault=new CredentialStore(ctx);
            File input=new File(ctx.getFilesDir(),"test-cookie.json");
            if(input.isFile()){
                test("cookie-import",()->{String text;try(FileInputStream in=new FileInputStream(input)){text=new String(FanqiePlugin.readLimited(in,512*1024),StandardCharsets.UTF_8);}finally{input.delete();}FanqiePlugin p=new FanqiePlugin(vault);p.setCookie(text);check("cookie-encrypted-roundtrip",new FanqiePlugin(vault).loggedIn());String disk=ctx.getSharedPreferences("vault",0).getString("cookie","");check("cookie-not-plaintext",!disk.contains("sessionid"));});
            }
            FanqiePlugin real=new FanqiePlugin(vault);
            Intent intent=new Intent(ctx,FanqieActivity.class);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);intent.putExtra("progress_test_readonly",true);activity=(FanqieActivity)startActivitySync(intent);waitForIdleSync();
            test("native-crypto",()->{check("sm3-abc",DesktopSigner.hex(DesktopSigner.sm3(DesktopSigner.utf("abc"))).equals("66c7f0f462eeedd9d1f2d46bdc10e4e24167c4875cf2f7a2297da02b8f4ba8e0"));byte[] key=DesktopSigner.hex("000102030405060708090a0b0c0d0e0f"),iv=new byte[16],v=DesktopSigner.utf("中文正文🔖");check("aes-unpad",Arrays.equals(v,DesktopSigner.aes(DesktopSigner.aes(v,key,iv,true),key,iv,false)));});
            test("cookie-validation",()->{try{CredentialStore.parseCookie("sessionid=abc\r\nInjected: x");throw new AssertionError("header injection accepted");}catch(Exception expected){check("cookie-header-injection-rejected",true);}String source=new JSONObject().put("cookies",new JSONArray().put(new JSONObject().put("name","sessionid").put("value","fake").put("domain","evil.test"))).toString();try{CredentialStore.parseCookie(source);throw new AssertionError("foreign cookie accepted");}catch(Exception expected){check("foreign-domain-cookie-rejected",true);}});
            final List<BookInfo> shelf=new ArrayList<>();
            test("live-bookshelf",()->{Page<BookInfo> first=real.bookshelf("");shelf.addAll(first.items);check("live-shelf-first-page",first.items.size()==20);check("live-shelf-metadata",first.items.stream().anyMatch(b->!b.id.equals(b.title)));Page<BookInfo> second=real.bookshelf(first.next);check("live-shelf-next-page",!second.items.isEmpty()&&!first.items.get(0).id.equals(second.items.get(0).id));});
            test("live-search",()->{Page<BookInfo> first=real.search("鲁迅","");check("live-search-books",!first.items.isEmpty());if(first.more){Page<BookInfo> next=real.search("鲁迅",first.next);Set<String> ids=new HashSet<>();for(BookInfo b:first.items)ids.add(b.id);check("live-search-server-cursor",!next.next.equals(first.next)&&next.items.stream().anyMatch(b->!ids.contains(b.id)));}});
            final ReadingProgress[] cloud={null};
            test("live-cloud-progress-readonly",()->{cloud[0]=real.readProgress("7134994653631220774");check("live-cloud-progress-read",cloud[0]!=null&&cloud[0].timestamp>0&&cloud[0].paragraph>=0);check("cloud-progress-is-not-local-chapter-one",cloud[0].chapter>0&&!cloud[0].dirty);});
            test("progress-storage-and-payload",()->{String scope="instrumentation-storage";ProgressStore storage=new ProgressStore(ctx,scope);ReadingProgress p=new ReadingProgress("123","456",2,7,3,10,1000,.2,.1,"md5",true);storage.put(p);ProgressStore recreated=new ProgressStore(ctx,scope);check("pending-survives-store-recreation",recreated.get("123").dirty&&recreated.pending().contains("123"));JSONObject row=FanqiePlugin.progressBody(p).getJSONArray("books").getJSONObject(0);check("upload-mobile-paragraph-schema",row.getInt("book_type")==0&&row.getString("paragraph_id").equals("7")&&row.getInt("paragraph_offset")==3);check("upload-millisecond-timestamp",row.getLong("read_timestamp_ms")==1000);check("store-keeps-character-and-paragraph",recreated.get("123").charOffset==10&&recreated.get("123").paragraph==7);ctx.deleteSharedPreferences("fanqie.progress.v1."+scope);});
            final List<ChapterInfo> catalog=new ArrayList<>();final ChapterContent[] live={null};final String[] commentText={""};
            test("live-reading",()->{catalog.addAll(real.directory("7134994653631220774"));check("live-catalog-md5",!catalog.isEmpty()&&!catalog.get(0).version.isEmpty());live[0]=real.chapter("7134994653631220774",catalog.get(0));check("live-decrypted-paragraphs",live[0].paragraphs.size()>20);check("live-preserved-idx",live[0].paragraphs.get(0).index==0&&live[0].paragraphs.get(1).index==1);});
            test("live-paragraph-comments",()->{if(live[0]==null)throw new Exception("chapter unavailable");Page<Comment> p=real.comments(live[0],live[0].paragraphs.get(0),"");check("live-real-paragraph-comments",!p.items.isEmpty());commentText[0]=p.items.get(0).text;if(p.more){Page<Comment> next=real.comments(live[0],live[0].paragraphs.get(0),p.next);check("live-comment-cursor",!next.items.isEmpty()&&!next.items.get(0).id.equals(p.items.get(0).id));}});
            test("publication-contract-mock",()->{Paragraph para=new Paragraph(7,"原文😀");ChapterContent chapter=new ChapterContent("123","456","测试章节","verified-md5",Arrays.asList(para));JSONObject body=FanqiePlugin.publicationBody(chapter,para,"模拟测试");check("publish-exact-paragraph",body.getJSONObject("comment_pos").getInt("start_para_index")==7);check("publish-md5-not-version-number",body.getString("item_version").equals("verified-md5"));check("publish-paragraph-service",body.getInt("service_id")==1&&body.getString("group_id").equals("456"));check("publish-offset-utf16",body.getJSONObject("comment_pos").getInt("end_word_pos")==4);try{FanqiePlugin.publicationBody(chapter,new Paragraph(7,"other"),"x");throw new AssertionError("foreign paragraph accepted");}catch(Exception expected){check("publish-foreign-target-rejected",true);}
                final int[] posts={0};FanqiePlugin fake=new FanqiePlugin(vault,(host,path,q,b,h)->{check("transport-not-real-network",path.equals("/reading/ugc/novel_comment/add/v/"));posts[0]++;return new JSONObject().put("code",0).put("data",new JSONObject().put("comment_id","mock-id"));});check("mock-publication-success",fake.publish(chapter,para,"测试").equals("mock-id"));check("mock-single-request",posts[0]==1);});
            test("watch-fullscreen-layout",()->{Thread.sleep(500);check("full-466-square-no-letterbox",decor().getWidth()==466&&decor().getHeight()==466);});
            test("ui-live-bookshelf",()->{if(shelf.isEmpty())throw new Exception("shelf unavailable");String label=shelf.get(0).title+(shelf.get(0).author.isEmpty()?"":"\n"+shelf.get(0).author);awaitButton(label);shot("bookshelf");check("ui-live-bookshelf-rendered",true);});
            test("ui-live-search",()->{click("搜索");main(()->find(decor(),EditText.class,null).setText("鲁迅"));click("开始搜索");awaitButton("加载更多");Thread.sleep(500);shot("search");check("ui-live-search-rendered",true);});
            test("ui-cloud-resume-readonly",()->{if(cloud[0]==null)throw new Exception("cloud unavailable");int target=-1;for(int i=0;i<catalog.size();i++)if(catalog.get(i).id.equals(cloud[0].itemId)){target=i;break;}if(target<0)throw new Exception("cloud chapter not in catalog");String button="继续阅读 · "+(target+1);main(()->activity.openBook(new BookInfo("7134994653631220774","云端进度验证","")));awaitButton(button);check("continue-uses-cloud-chapter",true);click(button);long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){final boolean[] visible={false};main(()->visible[0]=find(decor(),com.watchreader.ReaderView.class,null)!=null&&activity.current!=null&&activity.current.itemId.equals(cloud[0].itemId));if(visible[0])break;Thread.sleep(250);}com.watchreader.ReaderView view=find(decor(),com.watchreader.ReaderView.class,null);check("ui-cloud-chapter-restored",view!=null&&activity.current.itemId.equals(cloud[0].itemId));check("ui-cloud-paragraph-restored",view.getCharOffset()==ChapterPosition.offset(activity.current,cloud[0]));shot("cloud-reader");});
            test("ui-live-reader",()->{if(live[0]==null)throw new Exception("chapter unavailable");main(()->{activity.current=live[0];activity.showReader();});Thread.sleep(800);shot("reader");com.watchreader.ReaderView view=find(decor(),com.watchreader.ReaderView.class,null);check("ui-reader-view",view!=null);int before=view.getCharOffset();main(()->{long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,view.getWidth()*.8f,view.getHeight()*.5f,0),up=MotionEvent.obtain(now,now+30,MotionEvent.ACTION_UP,view.getWidth()*.8f,view.getHeight()*.5f,0);view.dispatchTouchEvent(down);view.dispatchTouchEvent(up);down.recycle();up.recycle();});int after=view.getCharOffset();check("reader-tap-turns-page",after>before);main(()->{activity.readerMenu();activity.showReader();});Thread.sleep(600);check("reader-progress-restored",find(decor(),com.watchreader.ReaderView.class,null).getCharOffset()==after);crownChecks();main(()->activity.readerMenu());click("段评 · 选择段落");shot("paragraphs");main(()->activity.showComments(live[0].paragraphs.get(0),"",false));if(commentText[0].isEmpty())throw new Exception("no expected comment");awaitText(commentText[0]);shot("comments");check("ui-real-comment-text-visible",true);});
            test("ui-publication-no-real-post",()->{FakePlugin fake=new FakePlugin();Paragraph p=new Paragraph(0,"只在本地模拟测试的原文");ChapterContent ch=new ChapterContent("123","456","测试章节","md5",Arrays.asList(p));main(()->{activity.plugin=fake;activity.current=ch;activity.selected=p;activity.compose(p,"");});main(()->find(decor(),EditText.class,null).setText("本地模拟段评"));click("预览发送");check("preview-does-not-send",fake.posts==0);shot("confirm");click("取消");check("cancel-does-not-send",fake.posts==0);main(()->activity.preview(p,"本地模拟段评"));click("确认公开发送");Thread.sleep(700);check("confirm-one-mock-post",fake.posts==1);check("mock-target-correct",fake.lastItem.equals("456")&&fake.lastParagraph==0);
                main(()->{activity.plugin=real;activity.current=live[0];activity.home();});});
            test("lifecycle-stale-response",()->{FakePlugin delayed=new FakePlugin();delayed.delay=600;main(()->{activity.plugin=delayed;activity.home();activity.searchForm();});Thread.sleep(1100);check("stale-shelf-does-not-replace-search",find(decor(),EditText.class,null)!=null&&find(decor(),Button.class,"模拟书架\n测试")==null);main(()->{activity.plugin=real;activity.home();});});
            test("ui-local-reader",()->{File directory=new File(ctx.getFilesDir(),"books");directory.mkdirs();File book=new File(directory,"instrumentation-local.txt");try(FileOutputStream out=new FileOutputStream(book)){for(int i=0;i<100;i++)out.write(("测试段落 "+i+"：本地小说无需网络即可阅读。\n").getBytes(StandardCharsets.UTF_8));}Intent local=new Intent(ctx,com.watchreader.ReaderActivity.class);local.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);local.putExtra(com.watchreader.ReaderActivity.EXTRA_PATH,book.getAbsolutePath());Activity reader=startActivitySync(local);Thread.sleep(1200);check("local-txt-reader-reused",find(reader.getWindow().getDecorView(),com.watchreader.ReaderView.class,null).getCharCount()>0);shot("local-reader");main(reader::finish);book.delete();});
        }catch(Throwable e){failures.put("runner: "+e.getClass().getSimpleName());}
        finally{watchdog.shutdownNow();try{android.util.DisplayMetrics metrics=getTargetContext().getResources().getDisplayMetrics();report.put("checks",checks).put("failures",failures).put("real_public_posts",0).put("device",Build.MODEL+" API"+Build.VERSION.SDK_INT+" "+metrics.widthPixels+"x"+metrics.heightPixels+" density"+metrics.densityDpi);File output=new File(getTargetContext().getFilesDir(),"test-report.json");try(FileOutputStream stream=new FileOutputStream(output)){stream.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}done.putString("summary","checks="+checks.length()+" failures="+failures.length()+" real_posts=0");done.putString("failures",failures.toString());}catch(Exception ignored){}finish(failures.length()==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,done);}
    }
    static final class FakePlugin implements ReaderPlugin {
        volatile int posts=0;String lastItem="";int lastParagraph=-1;long delay;
        public String id(){return "mock";}public Page<BookInfo> bookshelf(String cursor)throws Exception{Thread.sleep(delay);return new Page<>(Arrays.asList(new BookInfo("123","模拟书架","测试")),"",false);}
        public Page<BookInfo> search(String q,String c){return new Page<>(Collections.emptyList(),"",false);}
        public List<ChapterInfo> directory(String id){return Collections.emptyList();}public ChapterContent chapter(String b,ChapterInfo c){return null;}
        public Page<Comment> comments(ChapterContent ch,Paragraph p,String c){return new Page<>(Collections.emptyList(),"",false);}
        public String publish(ChapterContent ch,Paragraph p,String text){posts++;lastItem=ch.itemId;lastParagraph=p.index;return "mock";}
    }
}
